const lv_image_dsc_t* get(Kind kind, bool large) {
    switch (kind) {
        case Kind::Clear: return large ? &kClear56 : &kClear32;
        case Kind::PartlyCloudy: return large ? &kPartlyCloudy56 : &kPartlyCloudy32;
        case Kind::Cloud: return large ? &kCloud56 : &kCloud32;
        case Kind::Rain: return large ? &kRain56 : &kRain32;
        case Kind::Snow: return large ? &kSnow56 : &kSnow32;
        case Kind::Thunder: return large ? &kThunder56 : &kThunder32;
        case Kind::Fog: return large ? &kFog56 : &kFog32;
    }
    return large ? &kCloud56 : &kCloud32;
}

